import {createSimulation} from '../../src/game/core/simulation.ts';
import {welfareFixture} from './welfare-dom-scenarios.mjs';
import {passedScenario} from './scenario-result.mjs';
/** Explicit injected starting snapshots, generated by the real deterministic core. No fabricated score. */
export function satisfactionFixture(mode){
 let state;if(['healthy','poor','interrupted'].includes(mode)){state=welfareFixture('healthy');if(mode==='poor'){for(const a of state.animals)Object.assign(a,{hunger:95,thirst:95,energy:85,enrichment:0});for(const r of state.world.resources)if(r.kind!=='perch'){r.stock=0;r.portions=[0,0];}}}
 const s=createSimulation(state);if(mode==='unreachable'||mode==='empty')s.buildHabitat({x:4,z:4},'habitat-feedback');
 const path=mode==='none'||mode==='unreachable'?[[1,7]]:[[1,7],[2,7],[3,7],[3,6],[3,5]];for(const[x,z]of path)s.buildPath({x,z});s.visitors(true);
 for(let t=0;t<1000;t++){const st=s.snapshot(),v=st.visitors.find(v=>v.phase==='viewing');if(mode==='none'||mode==='unreachable'){if(st.visitors.some(v=>st.tick-v.arrival.spawnTick===78))break;}else if(v&&(mode!=='interrupted'||v.experience.samples===5))break;s.advance(100);}
 const result=s.snapshot();s.dispose();if(result.visitorFlow.feedback.evaluated!==0)throw Error('Fixture must not pre-complete feedback');return result;
}
const frame=()=>new Promise(r=>requestAnimationFrame(r));
export async function runSatisfactionDomScenarios(root,inspect,setPaused,setLocale,seed,remount){
 const q=s=>root.querySelector(s),cases=[],check=(v,m)=>{if(!v)throw Error(m);},summary=()=>q('[data-visitor-satisfaction]').textContent,feedback=()=>[...root.querySelectorAll('[data-visitor-feedback],[data-visitor-outcome]')].map(e=>e.textContent).join(' ');
 const wait=async(p,ms=18000,care=false)=>{const end=performance.now()+ms;while(performance.now()<end){await frame();if(care)for(const k of ['food','water'])if(inspect()[k+'Stock']<4)q(`[data-${k}-command="refill"]`).click();if(p())return;}throw Error('Satisfaction condition timeout');};
 const run=async(id,fn)=>{const data=await fn();cases.push(passedScenario(id,{session:inspect(),summary:summary(),feedback:feedback(),...data}));};
 try{
 await seed('healthy');
 await run('pending-actual-view-is-unscored',()=>{check(inspect().visitorScored===0&&inspect().visitorObservationSamples===0&&summary().includes('No visits scored yet'),'pending fabricated score');check(inspect().visitorViewing===1,'real viewing fixture');});
 await run('healthy-observation-produces-positive-per-visitor-feedback',async()=>{setPaused(false);await wait(()=>inspect().visitorPositive===1);check(feedback().includes('✓ Satisfied')&&inspect().visitorScored===1,'positive feedback missing');});
 await run('summary-matches-actual-integer-visit-score-not-current-world-average',()=>{const s=inspect();check(summary().includes(Math.round(s.visitorScoreSum/s.visitorScored)+'/100')&&q('[data-visitor-feedback="comfortable"]'),'summary differs from actual visit');check(s.currency===1500,'feedback granted money');});
 await run('paused-feedback-and-observations-do-not-update-or-spam',async()=>{setPaused(true);const before=inspect(),text=summary();let writes=0;const o=new MutationObserver(()=>writes++);o.observe(q('[data-visitor-satisfaction]'),{childList:true,subtree:true,characterData:true});for(let i=0;i<15;i++)await frame();o.disconnect();const after=inspect();for(const k of ['simulationTick','visitorEvaluated','visitorScored','visitorScoreSum','visitorObservationSamples','visitorObservationSum'])check(before[k]===after[k],k+' changed');check(writes===0&&text===summary(),'paused announcement spam');return {before,after,writes};});
 await run('ID-EN-outcome-cause-summary-and-aria-are-complete',()=>{setLocale('id');check(summary().includes('Kepuasan pengunjung')&&feedback().includes('✓ Puas')&&feedback().includes('Kesejahteraan satwa'),'ID outcome missing');check(q('[data-visitor-recent]').getAttribute('aria-label')==='Umpan balik pengunjung terakhir','ID aria');setLocale('en');check(summary().includes('Guest satisfaction')&&!feedback().includes('{'),'EN feedback placeholders');});
 await run('poor-observation-is-concerned-with-concrete-care-action',async()=>{await seed('poor');setPaused(false);await wait(()=>inspect().visitorNegative===1);check(feedback().includes('! Concerned')&&feedback().includes('restore their care needs')&&inspect().visitorScoreSum<60,'poor cause/action missing');});
 await run('actual-refill-care-recovers-later-visit-without-overwriting-the-poor-result',async()=>{const before=inspect(),started=performance.now();for(const k of ['food','water'])q(`[data-${k}-command="refill"]`).click();await wait(()=>inspect().visitorPositive>=1,105000,true);check(inspect().visitorNegative>=before.visitorNegative&&inspect().visitorScored>=2,'recovery overwrote poor visit');check(feedback().includes('Satisfied')&&inspect().currency===1500,'real recovery missing');setPaused(true);return {before,elapsedTicks:inspect().simulationTick-before.simulationTick,elapsedMs:performance.now()-started,method:'actual product refill controls and autonomous care/visitor ticks after explicit poor starting fixture; no time/state injection during recovery'};});
 await run('no-habitat-explains-build-action-without-fake-welfare',async()=>{await seed('none');setPaused(false);await wait(()=>inspect().visitorEvaluated>0);setPaused(true);check(feedback().includes('! No habitat')&&feedback().includes('Build one')&&!feedback().includes('Observed animal welfare'),'no-habitat explanation');});
 await run('unreachable-habitat-explains-path-repair',async()=>{await seed('unreachable');setPaused(false);await wait(()=>inspect().visitorEvaluated>0);setPaused(true);check(feedback().includes('! Could not reach habitat')&&feedback().includes('missing path'),'unreachable cause');});
 await run('empty-real-view-explains-welcoming-animals',async()=>{await seed('empty');setPaused(false);await wait(()=>inspect().visitorEvaluated>0);setPaused(true);check(feedback().includes('! Empty habitat')&&feedback().includes('Welcome the macaws'),'empty cause');});
 await run('interrupted-partial-view-has-no-final-score-or-duplicate-outcome',async()=>{await seed('interrupted');setPaused(false);q('[data-visitors-command="close"]').click();await wait(()=>inspect().visitorInterrupted>0);setPaused(true);check(inspect().visitorScored===0&&feedback().includes('No final score')&&feedback().includes('entrance closed'),'interruption fabricated score');return {partialSamples:inspect().visitorObservationSamples};});
 await run('paused-remount-preserves-feedback-summary-and-no-stale-positive-row',async()=>{const before=inspect(),text=summary();await remount();const after=inspect();for(const k of ['visitorEvaluated','visitorScored','visitorScoreSum','visitorPositive','visitorNegative','visitorInterrupted','visitorObservationSamples','visitorObservationSum'])check(before[k]===after[k],k+' changed on remount');check(summary()===text&&!q('[data-visitor-feedback="comfortable"]'),'stale positive summary/row');return {before,after};});
 await run('fresh-healthy-evaluation-leaves-real-populated-feedback-scene',async()=>{await seed('healthy');setPaused(false);await wait(()=>inspect().visitorPositive===1);setPaused(true);check(inspect().visitorModels===3&&inspect().liveBirdModels===2&&feedback().includes('✓ Satisfied'),'final healthy feedback scene');});
 return {status:'PASS',physicalDevice:false,method:'Explicit deterministic injected starting snapshots; actual native WebGL and real unaccelerated observation/recovery ticks through labelled fixture controls; no pre-made satisfaction results',cases};
 }catch(error){return {status:'FAIL',error:String(error),cases,session:inspect()};}finally{setPaused(true);}
}
